import{_ as t,o as a,c as s,a2 as l}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"URI 프로토콜 (lertaro://)","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/uri-protocol.md","filePath":"ko-KR/user-guide/uri-protocol.md","lastUpdated":1787586465000}'),n={name:"ko-KR/user-guide/uri-protocol.md"};function i(o,e,r,d,p,c){return a(),s("div",null,[...e[0]||(e[0]=[l(`<h1 id="uri-프로토콜-lertaro" tabindex="-1">URI 프로토콜 (lertaro://) <a class="header-anchor" href="#uri-프로토콜-lertaro" aria-label="Permalink to &quot;URI 프로토콜 (lertaro://)&quot;">​</a></h1><p>Lertaro는 처음 실행될 때 Windows 시스템에 커스텀 프로토콜 **<code>lertaro://</code>**를 자동으로 등록합니다. 웹 하이퍼링크, 바탕화면 바로가기, 자동화 스크립트 또는 타사 소프트웨어에서 이 프로토콜을 통해 특정 검색을 호출하거나 설정 페이지로 즉시 이동하고 파일 전송을 시작할 수 있습니다.</p><h2 id="_1-프로토콜-동작-및-단일-인스턴스-라우팅" tabindex="-1">1. 프로토콜 동작 및 단일 인스턴스 라우팅 <a class="header-anchor" href="#_1-프로토콜-동작-및-단일-인스턴스-라우팅" aria-label="Permalink to &quot;1. 프로토콜 동작 및 단일 인스턴스 라우팅&quot;">​</a></h2><ul><li><strong>설정 없이 즉시 사용</strong>: 레지스트리를 수동으로 편집할 필요가 없습니다. 앱 실행 시 자동으로 등록 및 무결성 검증이 수행됩니다.</li><li><strong>단일 인스턴스 라우팅</strong>: Lertaro가 이미 백그라운드에서 실행 중인 경우 <code>lertaro://</code> 링크를 열면 실행 중인 인스턴스로 요청이 즉시 전달되며 중복 프로세스가 생성되지 않습니다. 실행 중이 아니면 메인 앱을 시작하고 요청된 동작을 수행합니다.</li></ul><h2 id="_2-전체-uri-라우팅-명령어-목록" tabindex="-1">2. 전체 URI 라우팅 명령어 목록 <a class="header-anchor" href="#_2-전체-uri-라우팅-명령어-목록" aria-label="Permalink to &quot;2. 전체 URI 라우팅 명령어 목록&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">URI 명령어 형식</th><th style="text-align:left;">기능 설명 및 화면 동작</th></tr></thead><tbody><tr><td style="text-align:left;"><code>lertaro://</code></td><td style="text-align:left;">퀵 검색 윈도우 활성화 및 표시(<code>Ctrl</code> 더블 클릭과 동일).</td></tr><tr><td style="text-align:left;"><code>lertaro://search/[키워드]</code></td><td style="text-align:left;">퀵 윈도우를 열고 지정한 <code>[키워드]</code>를 미리 채워 즉시 필터링.</td></tr><tr><td style="text-align:left;"><code>lertaro://fullsearch/[키워드]</code></td><td style="text-align:left;">대형 메인 검색 윈도우를 열고 지정한 <code>[키워드]</code> 입력.</td></tr><tr><td style="text-align:left;"><code>lertaro://settings/page/[섹션]</code></td><td style="text-align:left;">설정 창을 열고 지정한 최상위 섹션 탭으로 즉시 전환.</td></tr><tr><td style="text-align:left;"><code>lertaro://settings/entry/[ID]</code></td><td style="text-align:left;">설정 창을 열고 특정 세부 설정 항목으로 점프하여 하이라이트 표시.</td></tr><tr><td style="text-align:left;"><code>lertaro://localsend</code></td><td style="text-align:left;">LocalSend 무선 파일 전송 빈 창 열기.</td></tr><tr><td style="text-align:left;"><code>lertaro://localsend/items/[인코딩된 절대 경로...]</code></td><td style="text-align:left;">LocalSend를 파일 모드로 열고 하나 이상의 파일/폴더 경로를 사전 등록.</td></tr><tr><td style="text-align:left;"><code>lertaro://localsend/text/[인코딩된 텍스트]</code></td><td style="text-align:left;">LocalSend를 텍스트 모드로 열고 지정한 텍스트를 입력 완료 상태로 표시.</td></tr></tbody></table><h3 id="설정-섹션-키워드-섹션" tabindex="-1">설정 섹션 키워드 <code>[섹션]</code> <a class="header-anchor" href="#설정-섹션-키워드-섹션" aria-label="Permalink to &quot;설정 섹션 키워드 \`[섹션]\`&quot;">​</a></h3><p>대소문자를 구분하지 않으며 설정 창의 사이드바 메뉴와 일치합니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Service      - 서비스 상태</span></span>
<span class="line"><span>Index        - 인덱싱 설정</span></span>
<span class="line"><span>General      - 일반 설정</span></span>
<span class="line"><span>Appearance   - 모양 및 테마</span></span>
<span class="line"><span>Hotkeys      - 단축키 설정</span></span>
<span class="line"><span>Plugins      - 플러그인 관리</span></span>
<span class="line"><span>Favorites    - 즐겨찾기</span></span>
<span class="line"><span>History      - 검색 기록</span></span>
<span class="line"><span>QuickPanel   - 퀵 패널</span></span>
<span class="line"><span>About        - 정보 및 업데이트</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><code>lertaro://settings/entry/[ID]</code>의 ID는 내장된 <a href="./instant-answers.html#2-키워드-실행-기능-내장-플러그인"><strong>설정 검색</strong></a>에서 동적으로 생성되는 내부 번호입니다. 버전 업데이트 시 변경될 수 있으므로 스크립트 연동 시에는 <code>lertaro://settings/page/[섹션]</code> 사용을 권장합니다.</p></div><h2 id="_3-localsend-파라미터-및-인코딩-규칙" tabindex="-1">3. LocalSend 파라미터 및 인코딩 규칙 <a class="header-anchor" href="#_3-localsend-파라미터-및-인코딩-규칙" aria-label="Permalink to &quot;3. LocalSend 파라미터 및 인코딩 규칙&quot;">​</a></h2><p>LocalSend 관련 URI를 사용할 때 모든 경로나 텍스트는 표준 URL 인코딩을 거쳐야 합니다(예: <code>:</code>는 <code>%3A</code>, <code>\\</code>는 <code>%5C</code>, 공백은 <code>%20</code>).</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 여러 파일 경로 사전 등록</span></span>
<span class="line"><span>lertaro://localsend/items/C%3A%5CUsers%5Ctestuser%5CDesktop%5Cdoc.pdf/D%3A%5CShared%5Cphotos</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 전송할 텍스트 사전 등록</span></span>
<span class="line"><span>lertaro://localsend/text/Hello%20from%20Lertaro%21</span></span></code></pre></div><ul><li><strong>보안 요구사항</strong>: 전달되는 모든 파일 경로는 로컬 머신에 실제 존재하는 절대 경로여야 합니다. 데이터가 포함된 링크는 기기 선택 화면만 열며 자동으로 전송을 시작하지 않습니다.</li></ul><h2 id="_4-외부-연동-실전-예제" tabindex="-1">4. 외부 연동 실전 예제 <a class="header-anchor" href="#_4-외부-연동-실전-예제" aria-label="Permalink to &quot;4. 외부 연동 실전 예제&quot;">​</a></h2><h3 id="마크다운-및-지식-베이스-링크" tabindex="-1">마크다운 및 지식 베이스 링크 <a class="header-anchor" href="#마크다운-및-지식-베이스-링크" aria-label="Permalink to &quot;마크다운 및 지식 베이스 링크&quot;">​</a></h3><p>Obsidian, Notion 또는 사내 문서에 직접 링크를 삽입할 수 있습니다.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Lertaro 테마 설정 열기</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">lertaro://settings/page/Appearance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">프로젝트 재무제표 검색</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">lertaro://search/재무제표%202026</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h3 id="바탕화면-바로가기-및-배치-스크립트" tabindex="-1">바탕화면 바로가기 및 배치 스크립트 <a class="header-anchor" href="#바탕화면-바로가기-및-배치-스크립트" aria-label="Permalink to &quot;바탕화면 바로가기 및 배치 스크립트&quot;">​</a></h3><p>바탕화면에서 바로가기를 만들고 대상에 다음을 입력합니다.</p><div class="language-cmd vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmd</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lertaro://fullsearch/D:\\Projects\\</span></span></code></pre></div><p>PowerShell 스크립트 호출 예시:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Start-Process</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;lertaro://settings/page/General&quot;</span></span></code></pre></div><h2 id="_5-보안-및-알-수-없는-라우팅-오류-처리" tabindex="-1">5. 보안 및 알 수 없는 라우팅 오류 처리 <a class="header-anchor" href="#_5-보안-및-알-수-없는-라우팅-오류-처리" aria-label="Permalink to &quot;5. 보안 및 알 수 없는 라우팅 오류 처리&quot;">​</a></h2><ul><li><strong>무음 안전 처리</strong>: 외부 웹페이지나 스크립트에서 URI를 임의로 호출할 수 있으므로, Lertaro는 모든 수신 URI를 엄격히 검증합니다. 잘못된 구문이나 존재하지 않는 경로는 조용히 무시되어 디버그 로그에만 기록되며 예기치 않은 오류를 유발하지 않습니다.</li></ul>`,25)])])}const k=t(n,[["render",i]]);export{g as __pageData,k as default};
